 12	
 13	const ringChunkSize = 10
 14	
 15	// Lex will buffer and return the tokens of a disposable *[Lexer].
 16	func Lex(source file.Source) ([]Token, error) {
 17		tokens := make([]Token, 0, ringChunkSize)
 18		l := New()
 19		l.Reset(source)
 20		for {
 21			t, err := l.Next()
 22			switch err {
 23			case nil:
 24				tokens = append(tokens, t)
 25			case io.EOF:
 26				return tokens, nil
 27			default:
 28				return nil, err
 29			}
 30		}
 31	}
 32	
 33	// New returns a reusable lexer.
 34	func New() *Lexer {
 35		return &Lexer{
 36			tokens: ring.New[Token](ringChunkSize),
 37		}
 38	}
 39	
 40	type Lexer struct {
 41		state      stateFn
 42		source     file.Source
 43		tokens     *ring.Ring[Token]
 44		err        *file.Error
 45		start, end struct {
 46			byte, rune int
 47		}
 48		eof bool
 49		// When true, keywords `if`/`else` are not treated as operators and
 50		// will be emitted as identifiers instead (for compatibility with custom if()).
 51		DisableIfOperator bool
 52	}
 53	
 54	func (l *Lexer) Reset(source file.Source) {
 55		l.source = source
 56		l.tokens.Reset()
 57		l.state = root
 58	}
 59	
 60	func (l *Lexer) Next() (Token, error) {
 61		for l.state != nil && l.err == nil && l.tokens.Len() == 0 {
 62			l.state = l.state(l)
 63		}
 64		if l.err != nil {
 65			return Token{}, l.err.Bind(l.source)
 66		}
 67		if t, ok := l.tokens.Dequeue(); ok {
 68			return t, nil
 69		}
 70		return Token{}, io.EOF
 71	}
 72	
 73	const eof rune = -1
 74	
 75	func (l *Lexer) commit() {
 76		l.start = l.end
 77	}
 78	
 79	func (l *Lexer) next() rune {
 80		if l.end.byte >= len(l.source.String()) {
 81			l.eof = true
 82			return eof
 83		}
 84		r, sz := utf8.DecodeRuneInString(l.source.String()[l.end.byte:])
 85		l.end.rune++
 86		l.end.byte += sz
 87		return r
 88	}
 89	
 90	func (l *Lexer) peek() rune {
 91		if l.end.byte < len(l.source.String()) {
 92			r, _ := utf8.DecodeRuneInString(l.source.String()[l.end.byte:])
 93			return r
 94		}
 95		return eof
 96	}
 97	
 98	func (l *Lexer) backup() {
 99		if l.eof {
100			l.eof = false
101		} else if l.end.rune > 0 {
102			_, sz := utf8.DecodeLastRuneInString(l.source.String()[:l.end.byte])
103			l.end.byte -= sz
104			l.end.rune--
105		}
106	}
107	
108	func (l *Lexer) emit(t Kind) {
109		l.emitValue(t, l.word())
110	}
111	
112	func (l *Lexer) emitValue(t Kind, value string) {
113		l.tokens.Enqueue(Token{
114			Location: file.Location{From: l.start.rune, To: l.end.rune},
115			Kind:     t,
116			Value:    value,
117		})
118		l.commit()
119	}
120	
121	func (l *Lexer) emitEOF() {
122		from := l.end.rune - 1
123		if from < 0 {
124			from = 0
125		}
126		to := l.end.rune - 0
127		if to < 0 {
128			to = 0
129		}
130		l.tokens.Enqueue(Token{
131			Location: file.Location{From: from, To: to},
132			Kind:     EOF,
133		})
134		l.commit()
135	}
136	
137	func (l *Lexer) skip() {
138		l.commit()
139	}
140	
141	func (l *Lexer) word() string {
142		return l.source.String()[l.start.byte:l.end.byte]
143	}
144	
145	func (l *Lexer) accept(valid string) bool {
146		if strings.ContainsRune(valid, l.peek()) {
147			l.next()
148			return true
149		}
150		return false
151	}
152	
153	func (l *Lexer) acceptRun(valid string) {
154		for l.accept(valid) {
155		}
156	}
