180	func digitVal(ch rune) int {
181		switch {
182		case '0' <= ch && ch <= '9':
183			return int(ch - '0')
184		case 'a' <= lower(ch) && lower(ch) <= 'f':
185			return int(lower(ch) - 'a' + 10)
186		}
187		return 16 // larger than any legal digit val
188	}
189	
190	func lower(ch rune) rune { return ('a' - 'A') | ch } // returns lower-case ch iff ch is ASCII letter
191	
192	func (l *Lexer) scanDigits(ch rune, base, n int) rune {
193		for n > 0 && digitVal(ch) < base {
194			ch = l.next()
195			n--
196		}
197		if n > 0 {
198			l.error("invalid char escape")
199		}
200		return ch
201	}
202	
203	func (l *Lexer) scanEscape(quote rune) rune {
204		ch := l.next() // read character after '/'
205		switch ch {
206		case 'a', 'b', 'f', 'n', 'r', 't', 'v', '\\', quote:
207			// nothing to do
208			ch = l.next()
209		case '0', '1', '2', '3', '4', '5', '6', '7':
210			ch = l.scanDigits(ch, 8, 3)
211		case 'x':
212			ch = l.scanDigits(l.next(), 16, 2)
213		case 'u':
214			// Support variable-length form: \u{XXXXXX}
215			if l.peek() == '{' {
216				// consume '{'
217				l.next()
218				// read 1-6 hex digits
219				digits := 0
220				for {
221					p := l.peek()
222					if p == '}' {
223						break
224					}
225					if digitVal(p) >= 16 {
226						l.error("invalid char escape")
227						return eof
228					}
229					if digits >= 6 {
230						l.error("invalid char escape")
231						return eof
232					}
233					l.next()
234					digits++
235				}
236				if l.peek() != '}' || digits == 0 {
237					l.error("invalid char escape")
238					return eof
239				}
240				// consume '}' and continue
241				l.next()
242				ch = l.next()
243				break
244			}
245			ch = l.scanDigits(l.next(), 16, 4)
246		case 'U':
247			ch = l.scanDigits(l.next(), 16, 8)
248		default:
249			l.error("invalid char escape")
250		}
251		return ch
252	}
253	
254	func (l *Lexer) scanString(quote rune) (n int) {
255		ch := l.next() // read character after quote
256		for ch != quote {
257			if ch == '\n' || ch == eof {
258				l.error("literal not terminated")
259				return
260			}
261			if ch == '\\' {
262				ch = l.scanEscape(quote)
263			} else {
264				ch = l.next()
265			}
266			n++
267		}
268		return
269	}
270	
271	func (l *Lexer) scanRawString(quote rune) (n int) {
272		var escapedQuotes int
273	loop:
274		for {
275			ch := l.next()
276			for ch == quote && l.peek() == quote {
277				// skip current and next char which are the quote escape sequence
278				l.next()
279				ch = l.next()
280				escapedQuotes++
281			}
282			switch ch {
283			case quote:
284				break loop
285			case eof:
286				l.error("literal not terminated")
287				return
288			}
289			n++
290		}
291		str := l.source.String()[l.start.byte+1 : l.end.byte-1]
292	
293		// handle simple case where no quoted backtick was found, then no allocation
294		// is needed for the new string
295		if escapedQuotes == 0 {
296			l.emitValue(String, str)
297			return
298		}
299	
300		var b strings.Builder
301		var skipped bool
302		b.Grow(len(str) - escapedQuotes)
303		for _, r := range str {
304			if r == quote {
305				if !skipped {
306					skipped = true
307					continue
308				}
309				skipped = false
310			}
311			b.WriteRune(r)
312		}
313		l.emitValue(String, b.String())
314		return
315	}

  1	package lexer
  2	
  3	import (
  4		"strings"
  5	
  6		"github.com/expr-lang/expr/parser/utils"
  7	)
  8	
  9	type stateFn func(*Lexer) stateFn
 10	
 11	func root(l *Lexer) stateFn {
 12		switch r := l.next(); {
 13		case r == eof:
 14			l.emitEOF()
 15			return nil
 16		case utils.IsSpace(r):
 17			l.skip()
 18			return root
 19		case r == '\'' || r == '"':
 20			l.scanString(r)
 21			str, err := unescape(l.word())
 22			if err != nil {
 23				l.error("%v", err)
 24			}
 25			l.emitValue(String, str)
 26		case r == '`':
 27			l.scanRawString(r)
 28		case (r == 'b' || r == 'B') && (l.peek() == '\'' || l.peek() == '"'):
 29			quote := l.next()
 30			l.scanString(quote)
 31			str, err := unescapeBytes(l.word()[1:]) // skip 'b'
 32			if err != nil {
 33				l.error("%v", err)
 34			}
 35			l.emitValue(Bytes, str)
 36		case '0' <= r && r <= '9':
 37			l.backup()
 38			return number
 39		case r == '?':
 40			return questionMark
 41		case r == '/':
 42			return slash
 43		case r == '#':
 44			return pointer
 45		case r == '|':
 46			l.accept("|")
 47			l.emit(Operator)
 48		case r == ':':
 49			l.accept(":")
 50			l.emit(Operator)
 51		case strings.ContainsRune("([{", r):
 52			l.emit(Bracket)
 53		case strings.ContainsRune(")]}", r):
 54			l.emit(Bracket)
 55		case strings.ContainsRune(",;%+-^", r): // single rune operator
 56			l.emit(Operator)
 57		case strings.ContainsRune("&!=*<>", r): // possible double rune operator
 58			l.accept("&=*")
 59			l.emit(Operator)
 60		case r == '.':
 61			l.backup()
 62			return dot
 63		case utils.IsAlphaNumeric(r):
 64			l.backup()
 65			return identifier
 66		default:
 67			return l.error("unrecognized character: %#U", r)
 68		}
 69		return root
 70	}
 71	
 72	func number(l *Lexer) stateFn {
 73		if !l.scanNumber() {
 74			return l.error("bad number syntax: %q", l.word())
 75		}
 76		l.emit(Number)
 77		return root
 78	}
 79	
 80	func (l *Lexer) scanNumber() bool {
 81		digits := "0123456789_"
 82		// Is it hex?
 83		if l.accept("0") {
 84			// Note: Leading 0 does not mean octal in floats.
 85			if l.accept("xX") {
 86				digits = "0123456789abcdefABCDEF_"
 87			} else if l.accept("oO") {
 88				digits = "01234567_"
 89			} else if l.accept("bB") {
 90				digits = "01_"
 91			}
 92		}
 93		l.acceptRun(digits)
 94		end := l.end
 95		if l.accept(".") {
 96			// Lookup for .. operator: if after dot there is another dot (1..2), it maybe a range operator.
 97			if l.peek() == '.' {
 98				// We can't backup() here, as it would require two backups,
 99				// and backup() func supports only one for now. So, save and
100				// restore it here.
101				l.end = end
102				return true
103			}
104			l.acceptRun(digits)
105		}
106		if l.accept("eE") {
107			l.accept("+-")
108			l.acceptRun(digits)
109		}
110		// Next thing mustn't be alphanumeric.
111		if utils.IsAlphaNumeric(l.peek()) {
112			l.next()
113			return false
114		}
115		return true
116	}
117	
118	func dot(l *Lexer) stateFn {
119		l.next()
120		if l.accept("0123456789") {
121			l.backup()
122			return number
123		}
124		l.accept(".")
125		l.emit(Operator)
126		return root
127	}
128	
129	func identifier(l *Lexer) stateFn {
130	loop:
131		for {
132			switch r := l.next(); {
133			case utils.IsAlphaNumeric(r):
134				// absorb
135			default:
136				l.backup()
137				switch l.word() {
138				case "not":
139					return not
140				case "in", "or", "and", "matches", "contains", "startsWith", "endsWith", "let":
141					l.emit(Operator)
142				case "if", "else":
143					if !l.DisableIfOperator {
144						l.emit(Operator)
145					} else {
146						l.emit(Identifier)
147					}
148				default:
149					l.emit(Identifier)
150				}
151				break loop
152			}
153		}
154		return root
155	}
156	
157	func not(l *Lexer) stateFn {
158		l.emit(Operator)
159	
160		l.skipSpaces()
161	
162		end := l.end
163	
164		// Get the next word.
165		for {
166			r := l.next()
167			if utils.IsAlphaNumeric(r) {
168				// absorb
169			} else {
170				l.backup()
171				break
172			}
173		}
174	
175		switch l.word() {
176		case "in", "matches", "contains", "startsWith", "endsWith":
177			l.emit(Operator)
178		default:
179			l.end = end
180		}
181		return root
182	}
183	
184	func questionMark(l *Lexer) stateFn {
185		l.accept(".?")
186		l.emit(Operator)
187		return root
188	}
189	
190	func slash(l *Lexer) stateFn {
191		if l.accept("/") {
192			return singleLineComment
193		}
194		if l.accept("*") {
195			return multiLineComment
196		}
197		l.emit(Operator)
198		return root
199	}
200	
201	func singleLineComment(l *Lexer) stateFn {
202		for {
203			r := l.next()
204			if r == eof || r == '\n' {
205				break
206			}
207		}
208		l.skip()
209		return root
210	}
211	
212	func multiLineComment(l *Lexer) stateFn {
213		for {
214			r := l.next()
215			if r == eof {
216				return l.error("unclosed comment")
217			}
218			if r == '*' && l.accept("/") {
219				break
220			}
221		}
222		l.skip()
223		return root
224	}
225	
226	func pointer(l *Lexer) stateFn {
227		l.accept("#")
228		l.emit(Operator)
229		for {
230			switch r := l.next(); {
231			case utils.IsAlphaNumeric(r): // absorb
232			default:
233				l.backup()
234				if l.word() != "" {
235					l.emit(Identifier)
236				}
237				return root
238			}
239		}
240	}

