 17	var (
 18		anyType       = reflect.TypeOf(new(any)).Elem()
 19		boolType      = reflect.TypeOf(true)
 20		intType       = reflect.TypeOf(0)
 21		floatType     = reflect.TypeOf(float64(0))
 22		stringType    = reflect.TypeOf("")
 23		arrayType     = reflect.TypeOf([]any{})
 24		mapType       = reflect.TypeOf(map[string]any{})
 25		timeType      = reflect.TypeOf(time.Time{})
 26		durationType  = reflect.TypeOf(time.Duration(0))
 27		byteSliceType = reflect.TypeOf([]byte(nil))
 28	
 29		anyTypeSlice = []reflect.Type{anyType}
