 31	
 32	// ParseCheck parses input expression and checks its types. Also, it applies
 33	// all provided patchers. In case of error, it returns error with a tree.
 34	func ParseCheck(input string, config *conf.Config) (*parser.Tree, error) {
 35		tree, err := parser.ParseWithConfig(input, config)
 36		if err != nil {
 37			return tree, err
 38		}
 39	
 40		_, err = new(Checker).PatchAndCheck(tree, config)
 41		if err != nil {
 42			return tree, err
 43		}
 44	
 45		return tree, nil
 46	}
 47	
 48	// Check calls Check on a disposable Checker.
 49	func Check(tree *parser.Tree, config *conf.Config) (reflect.Type, error) {
 50		return new(Checker).Check(tree, config)
 51	}
 52	
 53	type Checker struct {
 54		config          *conf.Config
 55		predicateScopes []predicateScope
 56		varScopes       []varScope
 57		err             *file.Error
 58		needsReset      bool
 59	}
 60	
 61	type predicateScope struct {
 62		collection Nature
 63		vars       []varScope
 64	}
 65	
 66	type varScope struct {
 67		name   string
 68		nature Nature
 69	}
 70	
 71	// PatchAndCheck applies all patchers and checks the tree.
 72	func (v *Checker) PatchAndCheck(tree *parser.Tree, config *conf.Config) (reflect.Type, error) {
 73		v.reset(config)
 74		if len(config.Visitors) > 0 {
 75			// Run all patchers that dont support being run repeatedly first
 76			v.runVisitors(tree, false)
 77	
 78			// Run patchers that require multiple passes next (currently only Operator patching)
 79			v.runVisitors(tree, true)
 80		}
 81		return v.Check(tree, config)
 82	}
 83	
 84	// Check checks types of the expression tree. It returns type of the expression
 85	// and error if any. If config is nil, then default configuration will be used.
 86	func (v *Checker) Check(tree *parser.Tree, config *conf.Config) (reflect.Type, error) {
 87		v.reset(config)
 88		return v.check(tree)
 89	}
 90	
 91	// Run visitors in a given config over the given tree
 92	// runRepeatable controls whether to filter for only vistors that require multiple passes or not
 93	func (v *Checker) runVisitors(tree *parser.Tree, runRepeatable bool) {
 94		for {
 95			more := false
 96			for _, visitor := range v.config.Visitors {
 97				// We need to perform types check, because some visitors may rely on
 98				// types information available in the tree.
 99				_, _ = v.Check(tree, v.config)
100	
101				r, repeatable := visitor.(interface {
102					Reset()
103					ShouldRepeat() bool
104				})
105	
106				if repeatable {
107					if runRepeatable {
108						r.Reset()
109						ast.Walk(&tree.Node, visitor)
110						more = more || r.ShouldRepeat()
111					}
112				} else {
113					if !runRepeatable {
114						ast.Walk(&tree.Node, visitor)
115					}
116				}
117			}
118	
119			if !more {
120				break
121			}
122		}
123	}
124	
125	func (v *Checker) check(tree *parser.Tree) (reflect.Type, error) {
126		nt := v.visit(tree.Node)
127	
128		// To keep compatibility with previous versions, we should return any, if nature is unknown.
129		t := nt.Type
130		if t == nil {
131			t = anyType
132		}
133	
134		if v.err != nil {
135			return t, v.err.Bind(tree.Source)
136		}
137	
138		if v.config.Expect != reflect.Invalid {
139			if v.config.ExpectAny {
140				if nt.IsUnknown(&v.config.NtCache) {
141					return t, nil
142				}
143			}
144	
145			switch v.config.Expect {
146			case reflect.Int, reflect.Int64, reflect.Float64:
147				if !nt.IsNumber() {
148					return nil, fmt.Errorf("expected %v, but got %s", v.config.Expect, nt.String())
149				}
150			default:
151				if nt.Kind != v.config.Expect {
152					return nil, fmt.Errorf("expected %v, but got %s", v.config.Expect, nt.String())
153				}
154			}
155		}
156	
157		return t, nil
158	}
159	
160	func (v *Checker) reset(config *conf.Config) {
161		if v.needsReset {
162			clearSlice(v.predicateScopes)
163			clearSlice(v.varScopes)
164			v.predicateScopes = v.predicateScopes[:0]
165			v.varScopes = v.varScopes[:0]
166			v.err = nil
167		}
168		v.needsReset = true
169	
170		if config == nil {
171			config = conf.New(nil)
172		}
173		v.config = config
174	}
175	
176	func clearSlice[S ~[]E, E any](s S) {
177		var zero E
178		for i := range s {
179			s[i] = zero
180		}
181	}
182	
183	func (v *Checker) visit(node ast.Node) Nature {
184		var nt Nature
185		switch n := node.(type) {
186		case *ast.NilNode:
187			nt = v.config.NtCache.NatureOf(nil)
188		case *ast.IdentifierNode:
189			nt = v.identifierNode(n)
190		case *ast.IntegerNode:
191			nt = v.config.NtCache.FromType(intType)
192		case *ast.FloatNode:
193			nt = v.config.NtCache.FromType(floatType)
194		case *ast.BoolNode:
195			nt = v.config.NtCache.FromType(boolType)
196		case *ast.StringNode:
197			nt = v.config.NtCache.FromType(stringType)
198		case *ast.BytesNode:
199			nt = v.config.NtCache.FromType(byteSliceType)
200		case *ast.ConstantNode:
201			nt = v.config.NtCache.FromType(reflect.TypeOf(n.Value))
202		case *ast.UnaryNode:
203			nt = v.unaryNode(n)
204		case *ast.BinaryNode:
205			nt = v.binaryNode(n)
206		case *ast.ChainNode:
207			nt = v.chainNode(n)
208		case *ast.MemberNode:
209			nt = v.memberNode(n)
210		case *ast.SliceNode:
211			nt = v.sliceNode(n)
212		case *ast.CallNode:
213			nt = v.callNode(n)
214		case *ast.BuiltinNode:
215			nt = v.builtinNode(n)
216		case *ast.PredicateNode:
217			nt = v.predicateNode(n)
218		case *ast.PointerNode:
219			nt = v.pointerNode(n)
220		case *ast.VariableDeclaratorNode:
221			nt = v.variableDeclaratorNode(n)
222		case *ast.SequenceNode:
223			nt = v.sequenceNode(n)
224		case *ast.ConditionalNode:
225			nt = v.conditionalNode(n)
226		case *ast.ArrayNode:
227			nt = v.arrayNode(n)
228		case *ast.MapNode:
229			nt = v.mapNode(n)
230		case *ast.PairNode:
231			nt = v.pairNode(n)
232		default:
233			panic(fmt.Sprintf("undefined node type (%T)", node))
234		}
235		node.SetNature(nt)
236		return nt
237	}
238	
239	func (v *Checker) error(node ast.Node, format string, args ...any) Nature {
240		if v.err == nil { // show first error
241			v.err = &file.Error{
242				Location: node.Location(),
243				Message:  fmt.Sprintf(format, args...),
244			}
245		}
246		return Nature{}
247	}
248	
249	func (v *Checker) identifierNode(node *ast.IdentifierNode) Nature {
250		for i := len(v.varScopes) - 1; i >= 0; i-- {
251			if v.varScopes[i].name == node.Value {
252				return v.varScopes[i].nature
253			}
254		}
255		if node.Value == "$env" {
256			return Nature{}
257		}
258	
259		return v.ident(node, node.Value, v.config.Strict, true)
260	}
261	
262	// ident method returns type of environment variable, builtin or function.
263	func (v *Checker) ident(node ast.Node, name string, strict, builtins bool) Nature {
264		if nt, ok := v.config.Env.Get(&v.config.NtCache, name); ok {
265			return nt
266		}
267		if builtins {
268			if fn, ok := v.config.Functions[name]; ok {
269				nt := v.config.NtCache.FromType(fn.Type())
270				if nt.TypeData == nil {
271					nt.TypeData = new(TypeData)
272				}
273				nt.TypeData.Func = fn
274				return nt
275			}
276			if fn, ok := v.config.Builtins[name]; ok {
277				nt := v.config.NtCache.FromType(fn.Type())
278				if nt.TypeData == nil {
279					nt.TypeData = new(TypeData)
280				}
281				nt.TypeData.Func = fn
282				return nt
283			}
284		}
285		if v.config.Strict && strict {
286			return v.error(node, "unknown name %s", name)
287		}
288		return Nature{}
289	}
290	
291	func (v *Checker) unaryNode(node *ast.UnaryNode) Nature {
292		nt := v.visit(node.Node)
293		nt = nt.Deref(&v.config.NtCache)
294	
295		switch node.Operator {
296	
297		case "!", "not":
298			if nt.IsBool() {
299				return v.config.NtCache.FromType(boolType)
300			}
301			if nt.IsUnknown(&v.config.NtCache) {
302				return v.config.NtCache.FromType(boolType)
303			}
304	
305		case "+", "-":
306			if nt.IsNumber() {
307				return nt
308			}
309			if nt.IsUnknown(&v.config.NtCache) {
310				return Nature{}
311			}
312	
313		default:
314			return v.error(node, "unknown operator (%s)", node.Operator)
315		}
316	
317		return v.error(node, `invalid operation: %s (mismatched type %s)`, node.Operator, nt.String())
318	}
319	
320	func (v *Checker) binaryNode(node *ast.BinaryNode) Nature {
321		l := v.visit(node.Left)
322		r := v.visit(node.Right)
323	
324		l = l.Deref(&v.config.NtCache)
325		r = r.Deref(&v.config.NtCache)
326	
327		switch node.Operator {
328		case "==", "!=":
329			if l.ComparableTo(&v.config.NtCache, r) {
330				return v.config.NtCache.FromType(boolType)
331			}
332	
333		case "or", "||", "and", "&&":
334			if l.IsBool() && r.IsBool() {
335				return v.config.NtCache.FromType(boolType)
336			}
337			if l.MaybeCompatible(&v.config.NtCache, r, BoolCheck) {
338				return v.config.NtCache.FromType(boolType)
339			}
340	
341		case "<", ">", ">=", "<=":
342			if l.IsNumber() && r.IsNumber() {
343				return v.config.NtCache.FromType(boolType)
344			}
345			if l.IsString() && r.IsString() {
346				return v.config.NtCache.FromType(boolType)
347			}
348			if l.IsTime() && r.IsTime() {
349				return v.config.NtCache.FromType(boolType)
350			}
351			if l.IsDuration() && r.IsDuration() {
352				return v.config.NtCache.FromType(boolType)
353			}
354			if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, StringCheck, TimeCheck, DurationCheck) {
355				return v.config.NtCache.FromType(boolType)
356			}
357	
358		case "-":
359			if l.IsNumber() && r.IsNumber() {
360				return l.PromoteNumericNature(&v.config.NtCache, r)
361			}
362			if l.IsTime() && r.IsTime() {
363				return v.config.NtCache.FromType(durationType)
364			}
365			if l.IsTime() && r.IsDuration() {
366				return v.config.NtCache.FromType(timeType)
367			}
368			if l.IsDuration() && r.IsDuration() {
369				return v.config.NtCache.FromType(durationType)
