 40	func (n *ConstantNode) String() string {
 41		if n.Value == nil {
 42			return "nil"
 43		}
 44		b, err := json.Marshal(n.Value)
 45		if err != nil {
 46			panic(err)
 47		}
 48		return string(b)
 49	}
