 65	// AsAny tells the compiler to expect any result.
 66	func AsAny() Option {
 67		return func(c *conf.Config) {
 68			c.ExpectAny = true
 69		}
 70	}
 71	
 72	// AsKind tells the compiler to expect kind of the result.
 73	func AsKind(kind reflect.Kind) Option {
 74		return func(c *conf.Config) {
 75			c.Expect = kind
 76			c.ExpectAny = true
 77		}
 78	}
 79	
 80	// AsBool tells the compiler to expect a boolean result.
 81	func AsBool() Option {
 82		return func(c *conf.Config) {
 83			c.Expect = reflect.Bool
 84			c.ExpectAny = true
 85		}
 86	}
 87	
 88	// AsInt tells the compiler to expect an int result.
 89	func AsInt() Option {
 90		return func(c *conf.Config) {
 91			c.Expect = reflect.Int
 92			c.ExpectAny = true
 93		}
 94	}
