 99			c.Expect = reflect.Int64
100			c.ExpectAny = true
101		}
102	}
103	
104	// AsFloat64 tells the compiler to expect a float64 result.
105	func AsFloat64() Option {
106		return func(c *conf.Config) {
107			c.Expect = reflect.Float64
108			c.ExpectAny = true
109		}
110	}
111	
112	// DisableIfOperator disables the `if ... else ...` operator syntax so a custom
113	// function named `if(...)` can be used without conflicts.
114	func DisableIfOperator() Option {
115		return func(c *conf.Config) {
116			c.DisableIfOperator = true
117		}
118	}
119	
120	// WarnOnAny tells the compiler to warn if expression return any type.
121	func WarnOnAny() Option {
122		return func(c *conf.Config) {
123			if c.Expect == reflect.Invalid {
124				panic("WarnOnAny() works only with combination with AsInt(), AsBool(), etc. options")
125			}
126			c.ExpectAny = false
