11	func Optimize(node *Node, config *conf.Config) error {
12		Walk(node, &inArray{})
13		for limit := 1000; limit >= 0; limit-- {
14			fold := &fold{}
15			Walk(node, fold)
16			if fold.err != nil {
17				return fold.err
18			}
19			if !fold.applied {
20				break
21			}
22		}
23		if config != nil && len(config.ConstFns) > 0 {
24			for limit := 100; limit >= 0; limit-- {
25				constExpr := &constExpr{
26					fns: config.ConstFns,
27				}
28				Walk(node, constExpr)
29				if constExpr.err != nil {
30					return constExpr.err
31				}
32				if !constExpr.applied {
33					break
34				}
35			}
36		}
37		Walk(node, &inRange{})
38		Walk(node, &filterMap{})
39		Walk(node, &filterLen{})
40		Walk(node, &filterLast{})
41		Walk(node, &filterFirst{})
42		Walk(node, &predicateCombination{})
43		Walk(node, &sumRange{})
44		Walk(node, &sumArray{})
45		Walk(node, &sumMap{})
46		Walk(node, &countAny{})
47		Walk(node, &countThreshold{})
48		return nil
49	}
50	
51	var (
52		boolType    = reflect.TypeOf(true)
53		integerType = reflect.TypeOf(0)
54		floatType   = reflect.TypeOf(float64(0))
55		stringType  = reflect.TypeOf("")
56	)
57	
58	func patchWithType(node *Node, newNode Node) {
59		switch n := newNode.(type) {
60		case *BoolNode:
61			newNode.SetType(boolType)
62		case *IntegerNode:
63			newNode.SetType(integerType)
64		case *FloatNode:
65			newNode.SetType(floatType)
66		case *StringNode:
67			newNode.SetType(stringType)
68		case *ConstantNode:
69			newNode.SetType(reflect.TypeOf(n.Value))
70		case *BinaryNode:
71			newNode.SetType(n.Type())
72		default:
73			panic(fmt.Sprintf("unknown type %T", newNode))
74		}
75		Patch(node, newNode)
76	}
77	
78	func patchCopyType(node *Node, newNode Node) {
79		t := (*node).Type()
80		newNode.SetType(t)
81		Patch(node, newNode)
82	}

