 10	type fold struct {
 11		applied bool
 12		err     *file.Error
 13	}
 14	
 15	func (fold *fold) Visit(node *Node) {
 16		patch := func(newNode Node) {
 17			fold.applied = true
 18			patchWithType(node, newNode)
 19		}
 20		patchCopy := func(newNode Node) {
 21			fold.applied = true
 22			patchCopyType(node, newNode)
 23		}
 24	
 25		switch n := (*node).(type) {
 26		case *UnaryNode:
 27			switch n.Operator {
 28			case "-":
 29				if i, ok := n.Node.(*IntegerNode); ok {
 30					patch(&IntegerNode{Value: -i.Value})
 31				}
 32				if i, ok := n.Node.(*FloatNode); ok {
 33					patch(&FloatNode{Value: -i.Value})
 34				}
 35			case "+":
 36				if i, ok := n.Node.(*IntegerNode); ok {
 37					patch(&IntegerNode{Value: i.Value})
 38				}
 39				if i, ok := n.Node.(*FloatNode); ok {
 40					patch(&FloatNode{Value: i.Value})
 41				}
 42			case "!", "not":
 43				if a := toBool(n.Node); a != nil {
 44					patch(&BoolNode{Value: !a.Value})
 45				}
 46			}
 47	
 48		case *BinaryNode:
 49			switch n.Operator {
 50			case "+":
 51				{
 52					a := toInteger(n.Left)
 53					b := toInteger(n.Right)
 54					if a != nil && b != nil {
 55						patch(&IntegerNode{Value: a.Value + b.Value})
 56					}
 57				}
 58				{
 59					a := toInteger(n.Left)
 60					b := toFloat(n.Right)
 61					if a != nil && b != nil {
 62						patch(&FloatNode{Value: float64(a.Value) + b.Value})
 63					}
 64				}
 65				{
 66					a := toFloat(n.Left)
 67					b := toInteger(n.Right)
 68					if a != nil && b != nil {
 69						patch(&FloatNode{Value: a.Value + float64(b.Value)})
 70					}
 71				}
 72				{
 73					a := toFloat(n.Left)
 74					b := toFloat(n.Right)
 75					if a != nil && b != nil {
 76						patch(&FloatNode{Value: a.Value + b.Value})
 77					}
 78				}
 79				{
 80					a := toString(n.Left)
 81					b := toString(n.Right)
 82					if a != nil && b != nil {
 83						patch(&StringNode{Value: a.Value + b.Value})
 84					}
 85				}
 86			case "-":
 87				{
 88					a := toInteger(n.Left)
 89					b := toInteger(n.Right)
 90					if a != nil && b != nil {
 91						patch(&IntegerNode{Value: a.Value - b.Value})
 92					}
 93				}
 94				{
 95					a := toInteger(n.Left)
 96					b := toFloat(n.Right)
 97					if a != nil && b != nil {
 98						patch(&FloatNode{Value: float64(a.Value) - b.Value})
 99					}
100				}
101				{
102					a := toFloat(n.Left)
103					b := toInteger(n.Right)
104					if a != nil && b != nil {
105						patch(&FloatNode{Value: a.Value - float64(b.Value)})
106					}
107				}
108				{
109					a := toFloat(n.Left)
110					b := toFloat(n.Right)
111					if a != nil && b != nil {
112						patch(&FloatNode{Value: a.Value - b.Value})
113					}
114				}
115			case "*":
116				{
117					a := toInteger(n.Left)
118					b := toInteger(n.Right)
119					if a != nil && b != nil {
120						patch(&IntegerNode{Value: a.Value * b.Value})
121					}
122				}
123				{
124					a := toInteger(n.Left)
125					b := toFloat(n.Right)
126					if a != nil && b != nil {
127						patch(&FloatNode{Value: float64(a.Value) * b.Value})
128					}
129				}
130				{
131					a := toFloat(n.Left)
132					b := toInteger(n.Right)
133					if a != nil && b != nil {
134						patch(&FloatNode{Value: a.Value * float64(b.Value)})
135					}
136				}
137				{
138					a := toFloat(n.Left)
139					b := toFloat(n.Right)
140					if a != nil && b != nil {
141						patch(&FloatNode{Value: a.Value * b.Value})
142					}
143				}
144			case "/":
145				{
146					a := toInteger(n.Left)
147					b := toInteger(n.Right)
148					if a != nil && b != nil {
149						patch(&FloatNode{Value: float64(a.Value) / float64(b.Value)})
150					}
151				}
152				{
153					a := toInteger(n.Left)
154					b := toFloat(n.Right)
155					if a != nil && b != nil {
156						patch(&FloatNode{Value: float64(a.Value) / b.Value})
157					}
158				}
159				{
160					a := toFloat(n.Left)
161					b := toInteger(n.Right)
162					if a != nil && b != nil {
163						patch(&FloatNode{Value: a.Value / float64(b.Value)})
164					}
165				}
166				{
167					a := toFloat(n.Left)
168					b := toFloat(n.Right)
169					if a != nil && b != nil {
170						patch(&FloatNode{Value: a.Value / b.Value})
171					}
172				}
173			case "%":
174				if a, ok := n.Left.(*IntegerNode); ok {
175					if b, ok := n.Right.(*IntegerNode); ok {
176						if b.Value == 0 {
177							fold.err = &file.Error{
178								Location: (*node).Location(),
179								Message:  "integer divide by zero",
180							}
181							return
182						}
183						patch(&IntegerNode{Value: a.Value % b.Value})
184					}
185				}
186			case "**", "^":
187				{
188					a := toInteger(n.Left)
189					b := toInteger(n.Right)
190					if a != nil && b != nil {
191						patch(&FloatNode{Value: math.Pow(float64(a.Value), float64(b.Value))})
192					}
193				}
194				{
195					a := toInteger(n.Left)
196					b := toFloat(n.Right)
197					if a != nil && b != nil {
198						patch(&FloatNode{Value: math.Pow(float64(a.Value), b.Value)})
199					}
200				}
201				{
202					a := toFloat(n.Left)
203					b := toInteger(n.Right)
204					if a != nil && b != nil {
205						patch(&FloatNode{Value: math.Pow(a.Value, float64(b.Value))})
206					}
207				}
208				{
209					a := toFloat(n.Left)
210					b := toFloat(n.Right)
211					if a != nil && b != nil {
212						patch(&FloatNode{Value: math.Pow(a.Value, b.Value)})
213					}
214				}
215			case "and", "&&":
216				a := toBool(n.Left)
217				b := toBool(n.Right)
218	
219				if a != nil && a.Value { // true and x
220					patchCopy(n.Right)
221				} else if b != nil && b.Value { // x and true
222					patchCopy(n.Left)
223				} else if (a != nil && !a.Value) || (b != nil && !b.Value) { // "x and false" or "false and x"
224					patch(&BoolNode{Value: false})
225				}
226			case "or", "||":
227				a := toBool(n.Left)
228				b := toBool(n.Right)
229	
230				if a != nil && !a.Value { // false or x
231					patchCopy(n.Right)
232				} else if b != nil && !b.Value { // x or false
233					patchCopy(n.Left)
234				} else if (a != nil && a.Value) || (b != nil && b.Value) { // "x or true" or "true or x"
235					patch(&BoolNode{Value: true})
236				}
237			case "==":
238				{
239					a := toInteger(n.Left)
240					b := toInteger(n.Right)
241					if a != nil && b != nil {
242						patch(&BoolNode{Value: a.Value == b.Value})
243					}
244				}
245				{
246					a := toString(n.Left)
247					b := toString(n.Right)
248					if a != nil && b != nil {
249						patch(&BoolNode{Value: a.Value == b.Value})
250					}
251				}
252				{
253					a := toBool(n.Left)
254					b := toBool(n.Right)
255					if a != nil && b != nil {
256						patch(&BoolNode{Value: a.Value == b.Value})
257					}
258				}
259			}
260	
261		case *ArrayNode:
262			if len(n.Nodes) > 0 {
263				for _, a := range n.Nodes {
264					switch a.(type) {
265					case *IntegerNode, *FloatNode, *StringNode, *BoolNode:
266						continue
267					default:
268						return
269					}
270				}
271				value := make([]any, len(n.Nodes))
272				for i, a := range n.Nodes {
273					switch b := a.(type) {
274					case *IntegerNode:
275						value[i] = b.Value
276					case *FloatNode:
277						value[i] = b.Value
278					case *StringNode:
279						value[i] = b.Value
280					case *BoolNode:
281						value[i] = b.Value
282					}
283				}
284				patch(&ConstantNode{Value: value})
285			}
286	
287		case *BuiltinNode:
288			// TODO: Move this to a separate visitor filter_filter.go
289			switch n.Name {
290			case "filter":
291				if len(n.Arguments) != 2 {
292					return
293				}
294				if base, ok := n.Arguments[0].(*BuiltinNode); ok && base.Name == "filter" {
295					patchCopy(&BuiltinNode{
296						Name: "filter",
297						Arguments: []Node{
298							base.Arguments[0],
299							&PredicateNode{
300								Node: &BinaryNode{
301									Operator: "&&",
302									Left:     base.Arguments[1].(*PredicateNode).Node,
303									Right:    n.Arguments[1].(*PredicateNode).Node,
304								},
305							},
306						},
307					})
308				}
309			}
310		}
311	}
