func (p *Parser) parseTryBlock(token Token) Node {
	p.expect(Bracket, "{")
	tryBody := p.parseSequenceExpression()
	p.expect(Bracket, "}")

	node := &TryNode{
		Try: tryBody,
	}

	if p.current.Is(Identifier, "catch") {
		p.next()
		// A catch clause may bind the error to a variable: catch err { ... }.
		// The name "finally" is not allowed as it would be ambiguous with the
		// finally clause.
		if p.current.Is(Identifier) && p.current.Value != "finally" {
			node.Name = p.current.Value
			p.next()
			// A catch clause may filter errors by a substring of the error
			// message: catch err is "timeout" { ... }.
			if p.current.Is(Identifier, "is") {
				p.next()
				if !p.current.Is(String) {
					p.error("expected string literal after is in catch clause (unexpected token %v)", p.current)
					return nil
