package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(code string, env any) {
	out, err := expr.Eval(code, env)
	fmt.Printf("%-72q => %v, err=%v\n", code, out, err)
}

func main() {
	// errtype: type and nil
	env := map[string]any{"a": 1, "b": "x", "n": nil}
	run(`try { a + b } catch e { errtype(e) }`, env)
	run(`try { n.foo } catch e { errtype(e) }`, env)
	run(`try { n.foo } catch e { string(e) }`, env)
	// errtype on non-error
	run(`errtype(42)`, nil)
	// retry: success after 2 failures
	calls := 0
	flaky := map[string]any{"flaky": func() (any, error) {
		calls++
		if calls < 3 {
			return nil, fmt.Errorf("fail %d", calls)
		}
		return "ok", nil
	}}
	run(`try { flaky() } catch { retry }`, flaky)
	fmt.Println("flaky calls:", calls)
	// retry: exhaustion
	calls2 := 0
	bad := map[string]any{"bad": func() (any, error) {
		calls2++
		return nil, fmt.Errorf("always fails")
	}}
	run(`try { bad() } catch { retry }`, bad)
	fmt.Println("bad calls:", calls2)
	// finally always runs (side-effect counter via env fn)
	marks := 0
	mark := map[string]any{"mark": func() int { marks++; return 0 }}
	run(`try { 1 } finally { mark() }`, mark)
	run(`try { throw("x") } catch { 2 } finally { mark() }`, mark)
	run(`try { throw("x") } finally { mark() }`, mark)
	fmt.Println("marks:", marks)
	// nested: inner filter mismatch propagates to outer
	run(`try { try { throw("a") } catch e is "nope" { 1 } } catch { 2 }`, nil)
	// stack restoration inside array build
	run(`[try { [1,2,3][5] } catch { 42 }, 7]`, nil)
	// try inside predicate
	run(`map([1,2,3], try { [10,20][#] } catch { -1 })`, nil)
	// error inside predicate caught outside
	run(`try { map([1,2], throw("x")) } catch { "caught" }`, nil)
	// VM reuse after error
	p, _ := expr.Compile(`try { 1 % 0 } catch { 42 }`, expr.Env(map[string]any{}))
	vm := expr.Run
	_ = vm
	for i := 0; i < 3; i++ {
		out, err := expr.Run(p, map[string]any{})
		fmt.Println("reuse:", out, err)
	}
	// sequence inside blocks
	run(`try { 1; 2 } catch { 3 }`, nil)
	run(`try { throw("x") } catch { 1; 2 }`, nil)
	// let + try
	run(`let x = try { [1][1] } catch { 5 }; x + 1`, nil)
	// try as operand
	run(`try { [1][9] } catch { 40 } + 2`, nil)
	// catch var usable in nested exprs
	run(`try { throw("boom") } catch e { errtype(e) + ":" + string(e) }`, nil)
	// retry counter is per-execution (loop over elements)
	n := 0
	flaky2 := map[string]any{"flaky2": func() (any, error) {
		n++
		if n%2 == 1 {
			return nil, fmt.Errorf("odd")
		}
		return n, nil
	}}
	run(`map([1,2,3], try { flaky2() } catch { retry })`, flaky2)
	fmt.Println("flaky2 calls:", n)
	// disassemble
	p2, _ := expr.Compile(`try { a } catch e is "x" { b } finally { c }`, expr.Env(map[string]any{"a": 1, "b": 2, "c": 3}))
	fmt.Println(p2.Disassemble())
}
EOF
cd /tmp/smoke && go run . 2>&1 | head -60

