package expr_test

import (
	"errors"
	"fmt"
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/parser"
	"github.com/expr-lang/expr/vm"
	"github.com/expr-lang/expr/vm/runtime"
)

func TestErrorHandling_try_function(t *testing.T) {
	t.Run("returns expression result on success", func(t *testing.T) {
		out, err := expr.Eval(`try(1, 2)`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("returns fallback on error", func(t *testing.T) {
		env := map[string]any{"arr": []int{1, 2, 3}, "i": 5}
		out, err := expr.Eval(`try(arr[i], 42)`, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("fallback is lazily evaluated", func(t *testing.T) {
		calls := 0
		env := map[string]any{
			"fallback": func() int { calls++; return 42 },
		}
		out, err := expr.Eval(`try(1, fallback())`, env)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
		assert.Equal(t, 0, calls)

		out, err = expr.Eval(`try(throw("x"), fallback())`, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
		assert.Equal(t, 1, calls)
	})

	t.Run("fallback may throw itself", func(t *testing.T) {
		out, err := expr.Eval(`try(throw("x"), try(throw("y"), "z"))`, nil)
		require.NoError(t, err)
		assert.Equal(t, "z", out)
	})

	t.Run("error in fallback propagates", func(t *testing.T) {
		_, err := expr.Eval(`try(throw("x"), throw("y"))`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "y")
	})

	t.Run("requires exactly two arguments", func(t *testing.T) {
		for _, code := range []string{`try()`, `try(1)`, `try(1, 2, 3)`} {
			_, err := expr.Compile(code)
			require.Error(t, err, code)
			assert.Contains(t, err.Error(), "invalid number of arguments (expected 2")
		}
	})

	t.Run("works with pipe operator", func(t *testing.T) {
		env := map[string]any{"arr": []int{1, 2, 3}, "i": 5}
		out, err := expr.Eval(`arr[i] | try(42)`, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("works in checked mode", func(t *testing.T) {
		env := map[string]any{"arr": []int{1, 2, 3}, "i": 5}
		program, err := expr.Compile(`try(arr[i], 42)`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})
}

func TestErrorHandling_try_catch_block(t *testing.T) {
	t.Run("try body result is used on success", func(t *testing.T) {
		out, err := expr.Eval(`try { 40 + 2 } catch { -1 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("catch handler result is used on error", func(t *testing.T) {
		env := map[string]any{"arr": []int{1, 2, 3}, "i": 5}
		out, err := expr.Eval(`try { arr[i] } catch { 42 }`, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("error is bound to a variable", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("boom") } catch err { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "boom", out)
	})

	t.Run("bound error is an error value", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("boom") } catch err { err }`, nil)
		require.NoError(t, err)
		caught, ok := out.(error)
		require.True(t, ok, "expected error, got %T", out)
		assert.Equal(t, "boom", caught.Error())
		var thrown *runtime.ThrownError
		require.True(t, errors.As(caught, &thrown))
		assert.Equal(t, "boom", thrown.Value)
	})

	t.Run("blocks support sequences", func(t *testing.T) {
		out, err := expr.Eval(`try { 1; 2 } catch { 3 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 2, out)

		out, err = expr.Eval(`try { throw("x") } catch { 1; 2 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
	})

	t.Run("try block can be nested and used as operand", func(t *testing.T) {
		out, err := expr.Eval(`try { [1][9] } catch { 40 } + 2`, nil)
		require.NoError(t, err)
		assert.Equal(t, 42, out)

		out, err = expr.Eval(`let x = try { [1][1] } catch { 5 }; x + 1`, nil)
		require.NoError(t, err)
		assert.Equal(t, 6, out)

		out, err = expr.Eval(`try { try { [1][9] } catch { 1 } } catch { 2 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("nested error propagates to outer catch", func(t *testing.T) {
		out, err := expr.Eval(`try { try { throw("a") } catch e is "nope" { 1 } } catch { 2 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
	})

	t.Run("error in catch handler propagates", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("a") } catch { throw("b") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "b")
	})

	t.Run("error in catch handler is caught by outer try", func(t *testing.T) {
		out, err := expr.Eval(`try { try { throw("a") } catch { throw("b") } } catch e { string(e) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "b", out)
	})

	t.Run("requires catch or finally", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 }`)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "expected catch or finally")
	})

	t.Run("requires try block", func(t *testing.T) {
		_, err := expr.Compile(`try 1 catch { 2 }`)
		require.Error(t, err)
	})

	t.Run("works in checked mode", func(t *testing.T) {
		type Env struct {
			Name string
		}
		program, err := expr.Compile(`try { Name } catch { "anon" }`, expr.Env(Env{}))
		require.NoError(t, err)
		out, err := expr.Run(program, Env{Name: "bob"})
		require.NoError(t, err)
		assert.Equal(t, "bob", out)
	})

	t.Run("catch variable can be shadowed safely", func(t *testing.T) {
		out, err := expr.Eval(`let e = "outer"; [try { throw("x") } catch e { string(e) }, e]`, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{"x", "outer"}, out)
	})
}

func TestErrorHandling_catch_filter(t *testing.T) {
	t.Run("catches errors containing the substring", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("network timeout") } catch err is "timeout" { "caught" }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught", out)
	})

	t.Run("error without the substring propagates", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("boom") } catch err is "timeout" { "caught" }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "boom")
	})

	t.Run("filter is applied to the error message", func(t *testing.T) {
		out, err := expr.Eval(`try { throw("boom") } catch err is "boom" { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "boom", out)
	})

	t.Run("non-matching filter falls through to outer catch", func(t *testing.T) {
		code := `
			try {
				try { throw("conversion failed") } catch err is "timeout" { "inner" }
			} catch err is "conversion" { "outer" }
		`
		out, err := expr.Eval(code, nil)
		require.NoError(t, err)
		assert.Equal(t, "outer", out)
	})

	t.Run("filter can classify runtime errors", func(t *testing.T) {
		env := map[string]any{"arr": []int{1}, "i": 5}
		out, err := expr.Eval(`try { arr[i] } catch err is "out of range" { -1 }`, env)
		require.NoError(t, err)
		assert.Equal(t, -1, out)
	})

	t.Run("filter requires a string literal", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 } catch err is 42 { 2 }`)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "expected string literal after is")
	})

	t.Run("filter requires a catch variable name", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 } catch is "x" { 2 }`)
		require.Error(t, err)
	})
}

func TestErrorHandling_finally(t *testing.T) {
	newEnv := func(marks *int) map[string]any {
		return map[string]any{"mark": func() int { *marks++; return 0 }}
	}

	t.Run("finally runs after successful try", func(t *testing.T) {
		marks := 0
		out, err := expr.Eval(`try { 1 } finally { mark() }`, newEnv(&marks))
		require.NoError(t, err)
		assert.Equal(t, 1, out)
		assert.Equal(t, 1, marks)
	})

	t.Run("finally runs after caught error", func(t *testing.T) {
		marks := 0
		out, err := expr.Eval(`try { throw("x") } catch { 2 } finally { mark() }`, newEnv(&marks))
		require.NoError(t, err)
		assert.Equal(t, 2, out)
		assert.Equal(t, 1, marks)
	})

	t.Run("finally runs before uncaught error propagates", func(t *testing.T) {
		marks := 0
		_, err := expr.Eval(`try { throw("x") } finally { mark() }`, newEnv(&marks))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "x")
		assert.Equal(t, 1, marks)
	})

	t.Run("finally runs when catch filter does not match", func(t *testing.T) {
		marks := 0
		_, err := expr.Eval(`try { throw("x") } catch err is "nope" { 1 } finally { mark() }`, newEnv(&marks))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "x")
		assert.Equal(t, 1, marks)
	})

	t.Run("finally runs after retry exhaustion", func(t *testing.T) {
		marks := 0
		_, err := expr.Eval(`try { throw("x") } catch { retry } finally { mark() }`, newEnv(&marks))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
		assert.Equal(t, 1, marks)
	})

	t.Run("finally result is discarded", func(t *testing.T) {
		out, err := expr.Eval(`try { 1 } finally { 2 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)

		out, err = expr.Eval(`try { throw("x") } catch { 2 } finally { 3 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
	})

	t.Run("finally error overrides try result", func(t *testing.T) {
		_, err := expr.Eval(`try { 1 } finally { throw("f") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "f")
	})

	t.Run("finally error overrides caught error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("a") } catch { "b" } finally { throw("f") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "f")
	})

	t.Run("error after finally is the original error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("original") } finally { 1 }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "original")
	})

	t.Run("finally in nested try", func(t *testing.T) {
		marks := 0
		env := newEnv(&marks)
		out, err := expr.Eval(`try { try { throw("x") } finally { mark() } } catch { 42 }`, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
		assert.Equal(t, 1, marks)
	})
}

func TestErrorHandling_throw(t *testing.T) {
	t.Run("throws a custom error", func(t *testing.T) {
		_, err := expr.Eval(`throw("boom")`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "boom")
	})

	t.Run("message is the string conversion of the value", func(t *testing.T) {
		for value, expected := range map[string]string{
			`42`:        "42",
			`1.5`:       "1.5",
			`true`:      "true",
			`[1, 2]`:    "[1 2]",
			`{a: "b"}`:  "map[a:b]",
			`"msg"`:     "msg",
			`nil`:       "<nil>",
		} {
			_, err := expr.Eval(fmt.Sprintf(`throw(%s)`, value), nil)
			require.Error(t, err, value)
			assert.Contains(t, err.Error(), expected)
		}
	})

	t.Run("thrown error can be caught", func(t *testing.T) {
		out, err := expr.Eval(`try { throw({code: 500}) } catch err { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "map[code:500]", out)
	})

	t.Run("requires exactly one argument", func(t *testing.T) {
		for _, code := range []string{`throw()`, `throw(1, 2)`} {
			_, err := expr.Compile(code)
			require.Error(t, err, code)
			assert.Contains(t, err.Error(), "invalid number of arguments (expected 1")
		}
	})

	t.Run("throw is a valid expression", func(t *testing.T) {
		out, err := expr.Eval(`try { true ? throw("x") : 1 } catch { 42 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})
}

func TestErrorHandling_retry(t *testing.T) {
	t.Run("retry re-executes the try body", func(t *testing.T) {
		calls := 0
		env := map[string]any{
			"flaky": func() (any, error) {
				calls++
				if calls < 3 {
					return nil, fmt.Errorf("failure %d", calls)
				}
				return "ok", nil
			},
		}
		out, err := expr.Eval(`try { flaky() } catch { retry }`, env)
		require.NoError(t, err)
		assert.Equal(t, "ok", out)
		assert.Equal(t, 3, calls)
	})

	t.Run("retry is limited to three retries", func(t *testing.T) {
		calls := 0
		env := map[string]any{
			"bad": func() (any, error) {
				calls++
				return nil, fmt.Errorf("always fails")
			},
		}
		_, err := expr.Eval(`try { bad() } catch { retry }`, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
		assert.Equal(t, 4, calls) // one initial attempt + three retries
	})

	t.Run("retry exhaustion has a distinct error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("x") } catch { retry }`, nil)
		require.Error(t, err)
		var exhausted *runtime.RetryExhaustedError
		require.True(t, errors.As(err, &exhausted))
		assert.Equal(t, 3, exhausted.Limit)
	})

	t.Run("retry exhaustion can be caught by an outer try", func(t *testing.T) {
		code := `try { try { throw("x") } catch { retry } } catch err { errtype(err) }`
		out, err := expr.Eval(code, nil)
		require.NoError(t, err)
		assert.Equal(t, "retry", out)
	})

	t.Run("retry outside a catch block raises a runtime error", func(t *testing.T) {
		_, err := expr.Eval(`retry`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry can only be used inside a catch block")
	})

	t.Run("retry in a try body raises a catchable runtime error", func(t *testing.T) {
		out, err := expr.Eval(`try { retry } catch err { string(err) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "retry can only be used inside a catch block", out)
	})

	t.Run("retry re-enters the try body after the error", func(t *testing.T) {
		attempts := 0
		handled := 0
		env := map[string]any{
			"flaky": func() (any, error) {
				attempts++
				if attempts == 1 {
					return nil, fmt.Errorf("first attempt fails")
				}
				return "recovered", nil
			},
			"note": func() int { handled++; return 0 },
		}
		out, err := expr.Eval(`try { flaky() } catch { note(); retry }`, env)
		require.NoError(t, err)
		assert.Equal(t, "recovered", out)
		assert.Equal(t, 2, attempts)
		assert.Equal(t, 1, handled)
	})

	t.Run("retry counter is per try execution", func(t *testing.T) {
		calls := 0
		env := map[string]any{
			"flaky": func() (any, error) {
				calls++
				if calls%2 == 1 {
					return nil, fmt.Errorf("odd call fails")
				}
				return calls, nil
			},
		}
		// Every element needs exactly one retry; the retry budget must reset
		// for every execution of the try block.
		out, err := expr.Eval(`map([1, 2, 3], try { flaky() } catch { retry })`, env)
		require.NoError(t, err)
		assert.Equal(t, []any{2, 4, 6}, out)
		assert.Equal(t, 6, calls)
	})

	t.Run("retry targets the innermost catch", func(t *testing.T) {
		calls := 0
		env := map[string]any{
			"flaky": func() (any, error) {
				calls++
				if calls == 1 {
					return nil, fmt.Errorf("first fails")
				}
				return "inner", nil
			},
		}
		code := `try { try { flaky() } catch { retry } } catch { "outer" }`
		out, err := expr.Eval(code, env)
		require.NoError(t, err)
		assert.Equal(t, "inner", out)
		assert.Equal(t, 2, calls)
	})

	t.Run("retry is not allowed in a finally block", func(t *testing.T) {
		_, err := expr.Eval(`try { 1 } finally { retry }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry can only be used inside a catch block")
	})
}

func TestErrorHandling_errtype(t *testing.T) {
	t.Run("classifies errors", func(t *testing.T) {
		env := map[string]any{
			"arr": []int{1, 2, 3},
			"i":   5,
			"s":   "not a number",
			"n":   nil,
			"a":   1,
			"b":   "x",
		}
		tests := []struct {
			code     string
			expected string
		}{
			{`try { arr[i] } catch err { errtype(err) }`, "index"},
			{`try { arr[0:10] } catch err { errtype(err) }`, "index"},
			{`try { int(s) } catch err { errtype(err) }`, "conversion"},
			{`try { float(s) } catch err { errtype(err) }`, "conversion"},
			{`try { a + b } catch err { errtype(err) }`, "type"},
			{`try { n.foo } catch err { errtype(err) }`, "nil"},
			{`try { throw("x") } catch err { errtype(err) }`, "custom"},
			{`try { throw(42) } catch err { errtype(err) }`, "custom"},
			{`try { try { throw("x") } catch { retry } } catch err { errtype(err) }`, "retry"},
		}
		for _, test := range tests {
			t.Run(test.code, func(t *testing.T) {
				out, err := expr.Eval(test.code, env)
				require.NoError(t, err)
				assert.Equal(t, test.expected, out)
			})
		}
	})

	t.Run("returns none for nil", func(t *testing.T) {
		out, err := expr.Eval(`errtype(nil)`, nil)
		require.NoError(t, err)
		assert.Equal(t, "none", out)
	})

	t.Run("returns custom for non-error values", func(t *testing.T) {
		out, err := expr.Eval(`errtype(42)`, nil)
		require.NoError(t, err)
		assert.Equal(t, "custom", out)
	})

	t.Run("returns a string", func(t *testing.T) {
		out, err := expr.Eval(`errtype(nil) + "!"`, nil)
		require.NoError(t, err)
		assert.Equal(t, "none!", out)
	})

	t.Run("requires exactly one argument", func(t *testing.T) {
		for _, code := range []string{`errtype()`, `errtype(1, 2)`} {
			_, err := expr.Compile(code)
			require.Error(t, err, code)
			assert.Contains(t, err.Error(), "invalid number of arguments (expected 1")
		}
	})
}

func TestErrorHandling_vm_integrity(t *testing.T) {
	t.Run("stack is restored after an error", func(t *testing.T) {
		out, err := expr.Eval(`[1, try { [1, 2, 3][5] } catch { 42 }, 7]`, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{1, 42, 7}, out)
	})

	t.Run("try works inside predicates", func(t *testing.T) {
		out, err := expr.Eval(`map([1, 2, 3], try { [10, 20][#] } catch { -1 })`, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{20, -1, -1}, out)
	})

	t.Run("scopes are restored after an error inside a predicate", func(t *testing.T) {
		code := `try { map([1, 2], throw("x")) } catch { "caught" }`
		out, err := expr.Eval(code, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught", out)

		// The VM must remain usable for further scope-based builtins.
		out, err = expr.Eval(code + ` + string(map([1], #)[0])`, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught1", out)
	})

	t.Run("vm is reusable after handled and unhandled errors", func(t *testing.T) {
		program, err := expr.Compile(`try { throw("x") } catch { 42 }`)
		require.NoError(t, err)
		v := &vm.VM{}
		for i := 0; i < 3; i++ {
			out, err := v.Run(program, nil)
			require.NoError(t, err)
			assert.Equal(t, 42, out)
		}

		failing, err := expr.Compile(`throw("x")`)
		require.NoError(t, err)
		for i := 0; i < 3; i++ {
			_, err := v.Run(failing, nil)
			require.Error(t, err)
			assert.Contains(t, err.Error(), "x")
		}

		out, err := v.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("errors in nested calls are caught", func(t *testing.T) {
		env := map[string]any{
			"fail": func() (any, error) { return nil, fmt.Errorf("call failed") },
		}
		out, err := expr.Eval(`try { fail() } catch err { string(err) }`, env)
		require.NoError(t, err)
		assert.Equal(t, "call failed", out)
	})

	t.Run("memory budget errors are catchable", func(t *testing.T) {
		program, err := expr.Compile(`try { 1..100000 } catch { "oom" }`)
		require.NoError(t, err)
		v := &vm.VM{MemoryBudget: 10}
		out, err := v.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, "oom", out)
	})
}

func TestErrorHandling_ast(t *testing.T) {
	t.Run("try block string representation", func(t *testing.T) {
		tests := []string{
			`try { a } catch { b }`,
			`try { a } catch e { b }`,
			`try { a } catch e is "x" { b }`,
			`try { a } finally { c }`,
			`try { a } catch { b } finally { c }`,
			`try { a } catch e is "x" { b } finally { c }`,
			`try { a } catch e { retry }`,
		}
		for _, code := range tests {
			t.Run(code, func(t *testing.T) {
				tree, err := parser.Parse(code)
				require.NoError(t, err)
				assert.Equal(t, code, tree.Node.String())
				// The string representation must be parseable again.
				_, err = parser.Parse(tree.Node.String())
				require.NoError(t, err)
			})
		}
	})

	t.Run("disassemble", func(t *testing.T) {
		program, err := expr.Compile(`try { a } catch e is "x" { b } finally { c }`,
			expr.Env(map[string]any{"a": 1, "b": 2, "c": 3}))
		require.NoError(t, err)
		out := program.Disassemble()
		for _, op := range []string{"OpTryFinally", "OpTry", "OpTryEnd", "OpMatchError", "OpStoreError", "OpRethrow"} {
			assert.Contains(t, out, op)
		}
	})
}

func TestErrorHandling_overrides(t *testing.T) {
	t.Run("try can be overridden by an env function", func(t *testing.T) {
		env := map[string]any{
			"try": func(a, b int) int { return a + b },
		}
		program, err := expr.Compile(`try(1, 2)`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 3, out)
	})

	t.Run("block form is unaffected by an env function named try", func(t *testing.T) {
		env := map[string]any{
			"try": func(a, b int) int { return a + b },
		}
		program, err := expr.Compile(`try { [1][9] } catch { 42 }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})
}

func TestErrorHandling_typing(t *testing.T) {
	t.Run("try expression type is combined from both branches", func(t *testing.T) {
		program, err := expr.Compile(`try(1, 2)`, expr.Env(nil), expr.AsInt())
		require.NoError(t, err)
		out, err := expr.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("try block type is combined from both branches", func(t *testing.T) {
		program, err := expr.Compile(`try { 1 } catch { 2 }`, expr.Env(nil), expr.AsInt())
		require.NoError(t, err)
		out, err := expr.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("try with only finally has the type of the try body", func(t *testing.T) {
		program, err := expr.Compile(`try { 1 } finally { "cleanup" }`, expr.Env(nil), expr.AsInt())
		require.NoError(t, err)
		out, err := expr.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("type errors inside blocks are still reported", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 + "a" } catch { 2 }`, expr.Env(nil))
		require.Error(t, err)

		_, err = expr.Compile(`try { 1 } catch { 2 + "a" }`, expr.Env(nil))
		require.Error(t, err)

		_, err = expr.Compile(`try { 1 } finally { 2 + "a" }`, expr.Env(nil))
		require.Error(t, err)
	})

	t.Run("unknown name inside try is still reported", func(t *testing.T) {
		_, err := expr.Compile(`try { unknownName } catch { 2 }`, expr.Env(nil))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "unknown name unknownName")
	})
}

func TestErrorHandling_uncaught_error_locations(t *testing.T) {
	t.Run("uncaught thrown error has a location", func(t *testing.T) {
		_, err := expr.Eval(`throw("boom")`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "(1:1)")
	})

	t.Run("error rethrown after finally keeps a location", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("boom") } finally { 1 }`, nil)
		require.Error(t, err)
		assert.True(t, strings.Contains(err.Error(), "boom"))
		assert.Contains(t, err.Error(), "(1:")
	})
}

