		assert.Equal(t, 1, out)
	})

	t.Run("nested error propagates to outer catch", func(t *testing.T) {
		out, err := expr.Eval(`try { try { throw("a") } catch e is "nope" { 1 } } catch { 2 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
	})

	t.Run("error in catch handler propagates", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("a") } catch { throw("b") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "b")
	})

	t.Run("error in catch handler is caught by outer try", func(t *testing.T) {
		out, err := expr.Eval(`try { try { throw("a") } catch { throw("b") } } catch e { string(e) }`, nil)
		require.NoError(t, err)
		assert.Equal(t, "b", out)
	})

	t.Run("requires catch or finally", func(t *testing.T) {
		_, err := expr.Compile(`try { 1 }`)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "expected catch or finally")
	})

	t.Run("requires try block", func(t *testing.T) {
		_, err := expr.Compile(`try 1 catch { 2 }`)
		require.Error(t, err)
	})

	t.Run("works in checked mode", func(t *testing.T) {
		type Env struct {
			Name string
		}
		program, err := expr.Compile(`try { Name } catch { "anon" }`, expr.Env(Env{}))
		require.NoError(t, err)
		out, err := expr.Run(program, Env{Name: "bob"})
		require.NoError(t, err)
		assert.Equal(t, "bob", out)
	})

	t.Run("catch variable can be shadowed safely", func(t *testing.T) {
		out, err := expr.Eval(`let e = "outer"; [try { throw("x") } catch e { string(e) }, e]`, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{"x", "outer"}, out)
	})
}

