func TestErrorHandling_finally(t *testing.T) {
	newEnv := func(marks *int) map[string]any {
		return map[string]any{"mark": func() int { *marks++; return 0 }}
	}

	t.Run("finally runs after successful try", func(t *testing.T) {
		marks := 0
		out, err := expr.Eval(`try { 1 } finally { mark() }`, newEnv(&marks))
		require.NoError(t, err)
		assert.Equal(t, 1, out)
		assert.Equal(t, 1, marks)
	})

	t.Run("finally runs after caught error", func(t *testing.T) {
		marks := 0
		out, err := expr.Eval(`try { throw("x") } catch { 2 } finally { mark() }`, newEnv(&marks))
		require.NoError(t, err)
		assert.Equal(t, 2, out)
		assert.Equal(t, 1, marks)
	})

	t.Run("finally runs before uncaught error propagates", func(t *testing.T) {
		marks := 0
		_, err := expr.Eval(`try { throw("x") } finally { mark() }`, newEnv(&marks))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "x")
		assert.Equal(t, 1, marks)
	})

	t.Run("finally runs when catch filter does not match", func(t *testing.T) {
		marks := 0
		_, err := expr.Eval(`try { throw("x") } catch err is "nope" { 1 } finally { mark() }`, newEnv(&marks))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "x")
		assert.Equal(t, 1, marks)
	})

	t.Run("finally runs after retry exhaustion", func(t *testing.T) {
		marks := 0
		_, err := expr.Eval(`try { throw("x") } catch { retry } finally { mark() }`, newEnv(&marks))
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
		assert.Equal(t, 1, marks)
	})

	t.Run("finally result is discarded", func(t *testing.T) {
		out, err := expr.Eval(`try { 1 } finally { 2 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 1, out)

		out, err = expr.Eval(`try { throw("x") } catch { 2 } finally { 3 }`, nil)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
	})

	t.Run("finally error overrides try result", func(t *testing.T) {
		_, err := expr.Eval(`try { 1 } finally { throw("f") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "f")
	})

	t.Run("finally error overrides caught error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("a") } catch { "b" } finally { throw("f") }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "f")
	})

	t.Run("error after finally is the original error", func(t *testing.T) {
		_, err := expr.Eval(`try { throw("original") } finally { 1 }`, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "original")
	})

	t.Run("finally in nested try", func(t *testing.T) {
		marks := 0
		env := newEnv(&marks)
		out, err := expr.Eval(`try { try { throw("x") } finally { mark() } } catch { 42 }`, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
		assert.Equal(t, 1, marks)
	})
}

