func TestErrorHandling_vm_integrity(t *testing.T) {
	t.Run("stack is restored after an error", func(t *testing.T) {
		out, err := expr.Eval(`[1, try { [1, 2, 3][5] } catch { 42 }, 7]`, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{1, 42, 7}, out)
	})

	t.Run("try works inside predicates", func(t *testing.T) {
		out, err := expr.Eval(`map([1, 2, 3], try { [10, 20][#] } catch { -1 })`, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{20, -1, -1}, out)
	})

	t.Run("scopes are restored after an error inside a predicate", func(t *testing.T) {
		code := `try { map([1, 2], throw("x")) } catch { "caught" }`
		out, err := expr.Eval(code, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught", out)

		// The VM must remain usable for further scope-based builtins.
		out, err = expr.Eval(code + ` + string(map([1], #)[0])`, nil)
		require.NoError(t, err)
		assert.Equal(t, "caught1", out)
	})

	t.Run("vm is reusable after handled and unhandled errors", func(t *testing.T) {
		program, err := expr.Compile(`try { throw("x") } catch { 42 }`)
		require.NoError(t, err)
		v := &vm.VM{}
		for i := 0; i < 3; i++ {
			out, err := v.Run(program, nil)
			require.NoError(t, err)
			assert.Equal(t, 42, out)
		}

		failing, err := expr.Compile(`throw("x")`)
		require.NoError(t, err)
		for i := 0; i < 3; i++ {
			_, err := v.Run(failing, nil)
			require.Error(t, err)
			assert.Contains(t, err.Error(), "x")
		}

		out, err := v.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
	})

	t.Run("errors in nested calls are caught", func(t *testing.T) {
		env := map[string]any{
			"fail": func() (any, error) { return nil, fmt.Errorf("call failed") },
		}
		out, err := expr.Eval(`try { fail() } catch err { string(err) }`, env)
		require.NoError(t, err)
		assert.Equal(t, "call failed", out)
	})

	t.Run("memory budget errors are catchable", func(t *testing.T) {
		program, err := expr.Compile(`try { 1..100000 } catch { "oom" }`)
		require.NoError(t, err)
		v := &vm.VM{MemoryBudget: 10}
		out, err := v.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, "oom", out)
	})
}

