package main

import (
	"fmt"
	"strings"

	"github.com/expr-lang/expr"
)

func run(code string, env any) {
	p, err := expr.Compile(code, expr.Env(env))
	if err != nil {
		fmt.Printf("%-75q => COMPILE ERR: %v\n", code, firstLine(err.Error()))
		return
	}
	out, err := expr.Run(p, env)
	if err != nil {
		fmt.Printf("%-75q => RUN ERR: %v\n", code, firstLine(err.Error()))
		return
	}
	fmt.Printf("%-75q => %v\n", code, out)
}

func firstLine(s string) string { return strings.SplitN(s, "\n", 2)[0] }

func main() {
	env := map[string]any{"arr": []int{1, 2, 3}, "i": 5, "x": 1, "y": 0}
	// with optimizer enabled (expr.Compile default)
	run(`try { [1,2,3][5] } catch { 42 }`, env)
	run(`try(arr[i], -1)`, env)
	run(`try { x % y } catch { "div" }`, env)
	run(`try { x / y } catch { "div" }`, env) // float +Inf, no error
	// let inside try body
	run(`try { let a = [1, 2]; a[7] } catch { -1 }`, env)
	run(`try { let a = 1; a } catch { 2 }`, env)
	// sortBy / groupBy with try inside
	run(`sortBy([3, 1, 2], try { [10, 20][#] } catch { 99 })`, env)
	run(`groupBy([1, 2, 3], try { # % 2 } catch { -1 })`, env)
	run(`filter([1, 2, 3], try { # > 1 } catch { false })`, env)
	// deep nesting
	run(`try { try { try { try { throw("deep") } catch e is "no" { 1 } } catch e is "deep" { 2 } } catch { 3 } } catch { 4 }`, env)
	// ternary / if interplay
	run(`(try { throw("x") } catch { true }) ? "yes" : "no"`, env)
	run(`if try { [1][9] } catch { 0 } == 0 { "zero" } else { "other" }`, env)
	// throw inside catch binding
	run(`try { throw("a") } catch e { throw(e) }`, env)
	// retry with filter
	calls := 0
	env2 := map[string]any{"f": func() (any, error) {
		calls++
		if calls == 1 {
			return nil, fmt.Errorf("timeout error")
		}
		return "ok", nil
	}}
	run(`try { f() } catch e is "timeout" { retry }`, env2)
	fmt.Println("calls:", calls)
	// finally with let
	run(`try { 1 } finally { let c = 3; c }`, env)
	// try inside finally
	run(`try { throw("a") } finally { try { throw("b") } catch { 1 } }`, env)
	// finally throwing caught outside
	run(`try { try { 1 } finally { throw("f") } } catch e { string(e) }`, env)
	// throw non-string in filter
	run(`try { throw({code: 500}) } catch e is "500" { "matched" }`, env)
	// sequences with semicolons after try block
	run(`try { 1 } catch { 2 }; 3`, env)
	// map key named try / catch / retry
	run(`{try: 1, catch: 2, retry: 3}.try`, env)
	run(`let catch = 5; catch + 1`, env)
	// retry() as env function
	env3 := map[string]any{"retry": func() int { return 7 }}
	run(`retry()`, env3)
	// ::try bypass
	run(`::try([1][9], 42)`, env)
	// $env access
	run(`try { $env["missing"] } catch { "fb" }`, env)
	// errtype with date parse error (custom)
	run(`try { date("nope") } catch e { errtype(e) }`, env)
	// type via unary not on non-bool
	run(`try { !(x - x + 1) } catch e { errtype(e) }`, map[string]any{"x": "s"})
	// string(throw value)
	run(`try { throw(3.14) } catch e { string(e) }`, env)
	// catch var name shadowing outer
	run(`let e = "outer"; try { throw("x") } catch e { string(e) }`, env)
	// optional chaining inside try
	run(`try { nil?.foo ?? "dflt" } catch { "caught" }`, env)
	// nil member access hard error
	run(`try { $env.nilVar.deep } catch e { errtype(e) }`, map[string]any{"nilVar": nil})
}
EOF
