713	
714			case OpMatchError:
715				err := vm.currentError()
716				if !strings.Contains(err.Error(), program.Constants[arg].(string)) {
717					panic(err)
718				}
719	
720			case OpStoreError:
721				vm.Variables[arg] = vm.currentError()
722	
723			case OpRethrow:
724				panic(vm.currentError())
725	
726			case OpRetry:
727				index := -1
728				for i := len(vm.tryStack) - 1; i >= 0; i-- {
729					if vm.tryStack[i].retryable && vm.tryStack[i].inCatch {
730						index = i
731						break
732					}
733				}
734				if index < 0 {
735					panic("retry can only be used inside a catch block")
736				}
737				vm.tryStack = vm.tryStack[:index+1]
738				frame := &vm.tryStack[index]
739				if frame.retries >= maxRetries {
740					panic(&runtime.RetryExhaustedError{Limit: maxRetries})
741				}
742				frame.retries++
743				frame.inCatch = false
744				frame.err = nil
745				vm.restore(frame)
746				vm.ip = frame.tryIP
747	
748			default:
749				panic(fmt.Sprintf("unknown bytecode %#x", op))
750			}
751	
752			if debug && vm.debug {
753				vm.curr <- vm.ip
754			}
755		}
