760	// handleError redirects a runtime error to the innermost active try frame.
761	// Frames that are already handling an error are skipped and removed. When no
762	// frame can handle the error, handleError panics with it.
763	func (vm *VM) handleError(r any) {
764		err, ok := r.(error)
765		if !ok {
766			err = fmt.Errorf("%v", r)
767		}
768		for len(vm.tryStack) > 0 {
769			frame := &vm.tryStack[len(vm.tryStack)-1]
770			if frame.inCatch {
771				vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
772				continue
773			}
774			frame.inCatch = true
775			frame.err = runtime.WrapCaught(err)
776			vm.restore(frame)
777			vm.ip = frame.catchIP
778			return
779		}
780		panic(err)
781	}
782	
783	// restore resets the stack and the scopes to the state captured by the frame.
784	func (vm *VM) restore(frame *tryFrame) {
785		vm.Stack = vm.Stack[:frame.stackLen]
786		vm.Scopes = vm.Scopes[:frame.scopeLen]
787		if len(vm.Scopes) > 0 {
788			vm.currScope = vm.Scopes[len(vm.Scopes)-1]
789		} else {
790			vm.currScope = nil
791		}
792	}
793	
794	// currentError returns the error handled by the innermost frame.
795	func (vm *VM) currentError() error {
796		for i := len(vm.tryStack) - 1; i >= 0; i-- {
797			if vm.tryStack[i].err != nil {
798				return vm.tryStack[i].err
799			}
800		}
801		panic("no active error")
802	}
803	
804	func (vm *VM) push(value any) {
805		vm.Stack = append(vm.Stack, value)
806	}
807	
808	func (vm *VM) current() any {
809		if len(vm.Stack) == 0 {
810			panic("stack underflow")
811		}
812		return vm.Stack[len(vm.Stack)-1]
813	}
